<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Cache,Crypt,DB};
use Illuminate\Support\Str;
class AiSip {
 public function workerKey():?string {$p=storage_path('app/private/ai-worker.key');return app()->environment('testing')?config('ai_test.worker_key'):(is_readable($p)?trim(file_get_contents($p)):null);}
 public function ready():bool {return (bool)$this->workerKey()&&Cache::get('ai.voice.worker_seen',0)>time()-30;}
 public function workerAuth(Request $r):void {$key=$this->workerKey();$timestamp=$r->header('X-DiscAI-Time','');$nonce=$r->header('X-DiscAI-Nonce','');abort_unless($key&&ctype_digit($timestamp)&&abs(time()-(int)$timestamp)<=30&&preg_match('/^[a-f0-9]{32}$/D',$nonce),403);$expected=hash_hmac('sha256',$timestamp.'.'.$nonce.'.'.$r->path().'.'.$r->getContent(),$key);abort_unless(hash_equals($expected,$r->header('X-DiscAI-Signature','')),403);abort_unless(Cache::add('ai.worker.nonce.'.$nonce,1,60),409);}
 public function verify(Request $r,int $w):array {
  abort_if(strlen($r->getContent())>30000,413);$c=DB::table('ai_connections')->where('workspace_id',$w)->first();abort_unless($c?->sip_secret,403);$secret=Crypt::decryptString($c->sip_secret);$secret=base64_decode(preg_replace('/^whsec_/','',$secret),true);$stamp=$r->header('webhook-timestamp','');$id=$r->header('webhook-id','');abort_unless($secret&&ctype_digit($stamp)&&abs(time()-(int)$stamp)<=300&&preg_match('/^[a-zA-Z0-9_-]{1,160}$/D',$id),403);$sig=base64_encode(hash_hmac('sha256',$id.'.'.$stamp.'.'.$r->getContent(),$secret,true));$valid=false;foreach(explode(' ',$r->header('webhook-signature',''))as $s)if(str_starts_with($s,'v1,')&&hash_equals($sig,substr($s,3)))$valid=true;abort_unless($valid,403);$body=json_decode($r->getContent(),true);abort_unless(is_array($body),422);return $body;
 }
 public function configure(int $w,int $u,string $agent,array $d):array {
  $a=app(AiAgents::class);$a->row($w,$agent);$queue=DB::table('voice_live_queues')->where('workspace_id',$w)->where('id',$d['queue_id'])->firstOrFail();$cfg=app(AiProvider::class)->connection($w);abort_unless($cfg['sip_configured'],422,'Configure o projeto e a assinatura de webhook em Conexão e custos.');
  if($d['enabled']){app(AiProvider::class)->ready($w);$a->published($w,$agent);abort_unless($this->ready(),409,'O serviço de voz ainda não está conectado.');abort_unless(QueueRouting::incoming($queue),422,'Habilite a entrada da fila.');}
  $old=DB::table('ai_sip_bindings')->where('workspace_id',$w)->where('agent_id',$agent)->first();$token=bin2hex(random_bytes(24));$id=$old?->id??(string)Str::uuid();$row=['queue_id'=>$queue->id,'transfer_uri'=>$d['transfer_uri']??null,'enabled'=>$d['enabled'],'updated_at'=>now()];if(!$old||($d['rotate']??false))$row['route_hash']=hash('sha256',$token);else $token=null;
  DB::table('ai_sip_bindings')->updateOrInsert(['id'=>$id],$row+['workspace_id'=>$w,'agent_id'=>$agent,'created_at'=>$old?->created_at??now()]);app(VoiceLab::class)->audit($w,$u,'ai.sip.configured',$id,['queue_id'=>$queue->id,'enabled'=>$d['enabled']]);return ['id'=>$id,'route_token'=>$token,'webhook_url'=>rtrim(config('app.url'),'/').'/callbacks/ai/sip/'.$id,'sip_uri'=>'sip:'.$cfg['project_id'].'@sip.api.openai.com;transport=tls','enabled'=>$d['enabled']];
 }
 public function incoming(Request $r,string $id):array {
  $b=DB::table('ai_sip_bindings')->where('id',$id)->firstOrFail();$event=$this->verify($r,$b->workspace_id);if(($event['type']??'')!=='realtime.call.incoming')return ['ignored'=>true];$call=$event['data']['call_id']??'';abort_unless(is_string($call)&&preg_match('/^[a-zA-Z0-9_-]{1,160}$/D',$call),422);$token='';foreach($event['data']['sip_headers']??[]as $h)if(strtolower($h['name']??'')==='x-discai-route')$token=$h['value']??'';abort_unless(is_string($token)&&hash_equals($b->route_hash,hash('sha256',$token)),403);
  try{$s=DB::transaction(function()use($b,$call){DB::table('voice_runtime')->where('id',1)->lockForUpdate()->firstOrFail();if(DB::table('ai_sessions')->where('provider_call_id',$call)->exists())return null;$q=DB::table('voice_live_queues')->where('workspace_id',$b->workspace_id)->where('id',$b->queue_id)->first();abort_unless($b->enabled&&$this->ready()&&QueueRouting::incoming($q)&&QueueOperationSettings::open($q)&&!app(OperationPolicy::class)->voiceReason($b->workspace_id),409,'Atendimento de IA indisponível.');abort_if(app(VoiceCapacity::class)->full()||DB::table('ai_sessions')->where('channel','phone')->whereIn('status',['connecting','open','closing','transferring'])->count()>=20,429,'Capacidade de telefonia atingida.');$c=app(AiAgents::class)->published($b->workspace_id,$b->agent_id);app(AiProvider::class)->ready($b->workspace_id);app(AiAgents::class)->quota($b->workspace_id);$id=(string)Str::uuid();DB::table('ai_sessions')->insert(['id'=>$id,'workspace_id'=>$b->workspace_id,'agent_id'=>$b->agent_id,'sip_binding_id'=>$b->id,'provider_call_id'=>$call,'channel'=>'phone','mode'=>'premium','status'=>'connecting','config'=>json_encode($c),'revision'=>app(AiAgents::class)->row($b->workspace_id,$b->agent_id)->revision,'expires_at'=>now()->addSeconds($c['max_seconds']),'created_at'=>now(),'updated_at'=>now()]);return DB::table('ai_sessions')->find($id);});}catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){if(!in_array($e->getStatusCode(),[409,429],true))throw $e;if(Cache::add('ai.sip.reject.'.hash('sha256',$call),1,300)){try{app(AiProvider::class)->control($b->workspace_id,$call,'reject',['status_code'=>486]);}catch(\Throwable $ignore){}}return ['accepted'=>false,'reason'=>'unavailable'];}if(!$s)return ['duplicate'=>true];
  $c=json_decode($s->config,true);$session=app(AiAgents::class)->voiceConfig($c);$session['tools']=[['type'=>'function','name'=>'request_human','description'=>'Peça transferência à equipe quando o cliente pedir uma pessoa ou quando faltar uma informação. Aguarde o resultado antes de confirmar.','parameters'=>['type'=>'object','properties'=>[],'additionalProperties'=>false]],['type'=>'function','name'=>'end_conversation','description'=>'Encerre após a despedida, ou imediatamente quando o cliente pedir para parar.','parameters'=>['type'=>'object','properties'=>[],'additionalProperties'=>false]]];
  try{abort_unless(app(AiProvider::class)->control($s->workspace_id,$call,'accept',$session),502);DB::table('ai_sessions')->where('id',$s->id)->update(['status'=>'open','updated_at'=>now()]);}catch(\Throwable $e){DB::table('ai_sessions')->where('id',$s->id)->update(['status'=>'closing','expires_at'=>now()]);abort(502,'A operadora de IA não confirmou o atendimento.');}return ['accepted'=>true];
 }
 public function poll():array {
  Cache::put('ai.voice.worker_seen',time(),45);$sessions=[];foreach(DB::table('ai_sessions')->where('channel','phone')->where('status','open')->where('expires_at','>',now())->limit(20)->get()as $s){$c=DB::table('ai_connections')->where('workspace_id',$s->workspace_id)->first();$b=DB::table('ai_sip_bindings')->find($s->sip_binding_id);$a=DB::table('ai_agents')->find($s->agent_id);if(!$c?->enabled||!$b?->enabled||$a?->paused){$this->end($s);continue;}$sessions[]=['id'=>$s->id,'call_id'=>$s->provider_call_id,'api_key'=>Crypt::decryptString($c->credentials),'greeting'=>json_decode($s->config,true)['greeting'],'expires_at'=>\Carbon\CarbonImmutable::parse($s->expires_at)->timestamp];}return $sessions;
 }
 private function end(object $s):bool {$ok=app(AiProvider::class)->hangup($s->workspace_id,$s->provider_call_id);DB::table('ai_sessions')->where('id',$s->id)->update(['status'=>$ok?'closed':'closing','expires_at'=>now(),'updated_at'=>now()]);return $ok;}
 public function event(string $id,array $d):array {
  $s=DB::table('ai_sessions')->where('id',$id)->where('channel','phone')->firstOrFail();if($s->status!=='open')return ['ended'=>true];
  if($d['type']==='ended'){$this->end($s);return ['ended'=>true];}
  if($d['type']==='transcript'){$rid=(string)Str::uuid();DB::table('ai_turns')->insertOrIgnore(['id'=>$rid,'session_id'=>$s->id,'request_id'=>substr(hash('sha256',$d['event_id']),0,8).'-'.substr(hash('sha256',$d['event_id']),8,4).'-'.substr(hash('sha256',$d['event_id']),12,4).'-'.substr(hash('sha256',$d['event_id']),16,4).'-'.substr(hash('sha256',$d['event_id']),20,12),'request_hash'=>hash('sha256',$d['text']),'input'=>'','output'=>$d['text'],'status'=>'completed','action'=>'reply','created_at'=>now(),'updated_at'=>now()]);return ['ok'=>true];}
  if($d['type']==='handoff'){
   $b=DB::table('ai_sip_bindings')->find($s->sip_binding_id);$q=$b?DB::table('voice_live_queues')->find($b->queue_id):null;$ids=$q?json_decode($q->agent_ids,true):[];$available=false;foreach($ids as $u)if(AgentAvailability::available($s->workspace_id,$u,$q->id)&&!app(VoiceAgentCapacity::class)->busy($s->workspace_id,$u)){$available=true;break;}
   if(!$b?->transfer_uri||!$available)return ['ok'=>false,'message'=>'Não há transferência disponível agora. Informe isso com clareza e peça o melhor horário para a equipe retornar. Não confirme retorno agendado.'];
   // Lease once before REFER; never repeat a potentially successful transfer.
   $claimed=DB::table('ai_sessions')->where('id',$s->id)->where('status','open')->update(['status'=>'transferring']);if(!$claimed)return ['ok'=>false,'message'=>'Transferência já em processamento.'];
   try{$ok=app(AiProvider::class)->control($s->workspace_id,$s->provider_call_id,'refer',['target_uri'=>$b->transfer_uri]);}catch(\Throwable $e){$ok=false;}
   DB::table('ai_sessions')->where('id',$id)->update(['status'=>$ok?'transferring':'closing','summary'=>$ok?'Transferência solicitada ao destino SIP da fila.':'Transferência sem confirmação; encerrar e revisar.','updated_at'=>now(),'expires_at'=>$ok?now()->addSeconds(30):now()]);app(VoiceLab::class)->audit($s->workspace_id,null,'ai.voice.transfer',$id,['request_accepted'=>$ok,'queue_id'=>$q->id]);return ['ok'=>$ok,'ended'=>true];
  }
  return ['ok'=>false];
 }
}
